def count_error_lines(filename):
    with open(filename) as f:
        lines = f.readlines()
    error_lines = [line for line in lines if "ERROR" in line]
    return len(error_lines)

def count_error_lines(filename):
    with open(filename) as f:
        return sum(1 for line in f if "ERROR" in line)
